/** [sql-smdInput.xml] SmdInputMapper.getSeq **/    
SELECT COALESCE(MAX(ST02_SEQ)+1,1) AS ST02_SEQ
FROM TB_ST_02
WHERE ST02_COMPANY = #{company}
  AND ST02_FACTORY = #{factory}
  AND TO_CHAR(ST02_DAT, 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD')

mapper.update:
UPDATE TB_ST_01
   SET ST01_STOK = #{stock}
    , st01_district = #{st01District}
WHERE 1=1
AND st01_company = #{company}
AND st01_factory = #{factory}
 AND st01_lot_seq = #{lotSeq}

UPDATE tb_st_01
 -- 재고수량을 변경하는 경우
   SET st01_qty = st01_qty - #{outQty} + #{ipQty}

 -- 재고 차감 (출고등록/입고삭제)
   SET st01_qty =  st01_qty - #{outQty}

 -- 재고 증가 (입고등록/출고삭제)
   SET st01_qty =  st01_qty + #{ipQty}

 -- 재고실사 품목일때 기존의 수량 0
   SET st01_qty = '0'

WHERE 1=1
AND st01_company = #{company}
AND st01_factory = #{factory}
AND st01_code = #{code}
AND st01_stok = #{stock}

   AND st01_lot = #{lot}
   AND st01_lot_seq = #{lotSeq}

mapper.select:
		/** sql-smdInput.xml] SmdInputMapper.getLotInfo **/
        SELECT *
        FROM TB_ST_01 st01
        LEFT JOIN TB_ST_02 st02 ON st01.ST01_COMPANY = st02.ST02_COMPANY AND st01.ST01_FACTORY = st02.ST02_FACTORY AND st01.ST01_LOT_SEQ = st02.ST02_LOT_SEQ
        WHERE ST01_COMPANY = #{company}
          AND ST01_FACTORY = #{factory}
          AND ST01_CODE = #{st03Code}
          AND ST01_LOT = #{st03Lot}
          AND ST01_LOT_SEQ = #{st03LotSeq}

            AND ST01_STOK = #{stok}

          AND ST01_QTY > 0

SELECT *
FROM TB_QA_07
WHERE QA07_COMPANY = #{company}
  AND QA07_FACTORY = #{factory}
  AND QA07_CODE = #{st03Code}
  AND QA07_LOT = #{st03Lot}
  AND QA07_LOT_SEQ = #{st03LotSeq}

SELECT QA08_STATUS
FROM TB_QA_07 QA07
         LEFT JOIN TB_QA_08 QA08 ON QA07.QA07_COMPANY = QA08.QA08_COMPANY AND QA07.QA07_FACTORY = QA08.QA08_FACTORY AND QA07.QA07_CODE = QA08.QA08_CODE AND QA07.QA07_NO = QA08.QA07_NO
WHERE QA07_COMPANY = #{company}
  AND QA07_FACTORY = #{factory}
  AND QA07_CODE = #{st03Code}
  AND QA07_LOT_SEQ = #{st03LotSeq}
